import{_ as e,o as t,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"语言模型与概率生成","description":"理解语言模型、条件概率、下一个 Token 预测、自回归生成、参数化知识，以及确定性计算与随机解码的边界。","frontmatter":{"title":"语言模型与概率生成","description":"理解语言模型、条件概率、下一个 Token 预测、自回归生成、参数化知识，以及确定性计算与随机解码的边界。","verified_at":"2026-07-28","sources":["https://web.stanford.edu/~jurafsky/slp3/","https://arxiv.org/abs/2005.14165","https://arxiv.org/abs/2203.02155"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/foundations/model-principles/llm-probabilistic-generation.md","filePath":"py-agent/foundations/model-principles/llm-probabilistic-generation.md","lastUpdated":1785291406000}'),i={name:"py-agent/foundations/model-principles/llm-probabilistic-generation.md"};function l(o,a,s,d,h,p){return t(),n("div",null,[...a[0]||(a[0]=[r(`<h1 id="语言模型与概率生成" tabindex="-1">语言模型与概率生成 <a class="header-anchor" href="#语言模型与概率生成" aria-label="Permalink to &quot;语言模型与概率生成&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>大语言模型首先是一个<strong>条件概率模型</strong>：给定已经出现的 Token 序列，它为下一个可能出现的 Token 分配概率。聊天、摘要、翻译和代码生成看起来是不同能力，但对自回归语言模型而言，运行时都被转化成同一个基本操作：根据已有上下文预测下一个 Token，并把选中的 Token 接回上下文继续预测。</p><p>理解这一点，可以同时解释模型为什么能完成开放式任务，也解释为什么“语言流畅”不等于“事实正确”。</p><h2 id="_1-什么是语言模型" tabindex="-1">1. 什么是语言模型 <a class="header-anchor" href="#_1-什么是语言模型" aria-label="Permalink to &quot;1. 什么是语言模型&quot;">​</a></h2><h3 id="_1-1-模型描述序列的概率" tabindex="-1">1.1 模型描述序列的概率 <a class="header-anchor" href="#_1-1-模型描述序列的概率" aria-label="Permalink to &quot;1.1 模型描述序列的概率&quot;">​</a></h3><p>设一段文本被表示为 Token 序列 <code>x₁, x₂, ..., xₙ</code>。语言模型希望描述这个序列出现的概率。根据概率的链式法则，联合概率可以拆成一系列条件概率：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(x₁, x₂, ..., xₙ)</span></span>
<span class="line"><span>= P(x₁) · P(x₂ | x₁) · ... · P(xₙ | x₁, ..., xₙ₋₁)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>竖线右侧是已经给定的上下文，左侧是要预测的下一个 Token。模型不需要一次生成完整段落，只需反复解决“在当前上下文之后，哪些 Token 更可能出现”。</p><h3 id="_1-2-大语言模型的-大-指什么" tabindex="-1">1.2 大语言模型的“大”指什么 <a class="header-anchor" href="#_1-2-大语言模型的-大-指什么" aria-label="Permalink to &quot;1.2 大语言模型的“大”指什么&quot;">​</a></h3><p>“大”通常同时涉及参数规模、训练数据规模和训练计算量，但没有统一阈值。参数是训练得到的数值，不是一条条可直接读取的句子。规模扩大通常提升模式表达能力，却不自动保证事实更新、逻辑正确或安全行为。</p><h3 id="_1-3-语言建模不是理解的操作性定义" tabindex="-1">1.3 语言建模不是理解的操作性定义 <a class="header-anchor" href="#_1-3-语言建模不是理解的操作性定义" aria-label="Permalink to &quot;1.3 语言建模不是理解的操作性定义&quot;">​</a></h3><p>模型可以从大量数据中学习语法、语义关系、文体、知识关联和任务模式，因此表现出翻译、问答和推理能力。是否把这些能力称为“理解”属于更宽的认知讨论；应用开发更需要可检验的描述：给定输入分布，模型在哪些任务上能稳定产生满足标准的输出。</p><h2 id="_2-下一个-token-预测" tabindex="-1">2. 下一个 Token 预测 <a class="header-anchor" href="#_2-下一个-token-预测" aria-label="Permalink to &quot;2. 下一个 Token 预测&quot;">​</a></h2><h3 id="_2-1-输出是整个词表的分布" tabindex="-1">2.1 输出是整个词表的分布 <a class="header-anchor" href="#_2-1-输出是整个词表的分布" aria-label="Permalink to &quot;2.1 输出是整个词表的分布&quot;">​</a></h3><p>假设上下文是“巴黎是法国的”，模型不会只返回一个答案，而会对词表中每个候选 Token 给出一个分数，再转换成概率分布：</p><table tabindex="0"><thead><tr><th>候选 Token</th><th style="text-align:right;">示意概率</th></tr></thead><tbody><tr><td>首都</td><td style="text-align:right;">0.78</td></tr><tr><td>城市</td><td style="text-align:right;">0.09</td></tr><tr><td>中心</td><td style="text-align:right;">0.04</td></tr><tr><td>其他 Token 合计</td><td style="text-align:right;">0.09</td></tr></tbody></table><p>这些数字只是示意。真正词表可能包含数万到数十万个 Token，而且“首都”是否是一个 Token 由分词器决定。</p><h3 id="_2-2-训练目标提供局部反馈" tabindex="-1">2.2 训练目标提供局部反馈 <a class="header-anchor" href="#_2-2-训练目标提供局部反馈" aria-label="Permalink to &quot;2.2 训练目标提供局部反馈&quot;">​</a></h3><p>预训练时，已知文本中的真实下一个 Token 可以作为目标。模型给真实 Token 的概率越低，损失通常越大；优化算法据此调整参数。大量局部预测训练会迫使模型学习能帮助预测的统计结构，包括句法、语义、事实关联和长距离依赖。</p><p>训练目标是预测数据中的 Token，不是直接写入一套经审计的事实数据库。模型可能压缩并泛化数据模式，也可能混合冲突信息或补出貌似合理的内容。</p><h2 id="_3-自回归生成" tabindex="-1">3. 自回归生成 <a class="header-anchor" href="#_3-自回归生成" aria-label="Permalink to &quot;3. 自回归生成&quot;">​</a></h2><h3 id="_3-1-生成是一个反馈循环" tabindex="-1">3.1 生成是一个反馈循环 <a class="header-anchor" href="#_3-1-生成是一个反馈循环" aria-label="Permalink to &quot;3.1 生成是一个反馈循环&quot;">​</a></h3><p>一次生成可以抽象为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入上下文</span></span>
<span class="line"><span>  -&gt; 模型计算下一个 Token 的分布</span></span>
<span class="line"><span>  -&gt; 解码策略选择一个 Token</span></span>
<span class="line"><span>  -&gt; 把该 Token 追加到上下文</span></span>
<span class="line"><span>  -&gt; 再次计算</span></span>
<span class="line"><span>  -&gt; 遇到停止条件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>之所以叫“自回归”，是因为模型先前生成的结果会成为后续预测的输入。早期一个看似很小的选择，可能把后续内容带向完全不同的路径。</p><h3 id="_3-2-一次预测正确不等于整段正确" tabindex="-1">3.2 一次预测正确不等于整段正确 <a class="header-anchor" href="#_3-2-一次预测正确不等于整段正确" aria-label="Permalink to &quot;3.2 一次预测正确不等于整段正确&quot;">​</a></h3><p>如果长输出中的每一步都存在小概率偏差，误差会随序列延伸而积累。模型还可能基于自己刚生成的错误前提继续推导，形成内部连贯但外部错误的段落。因此输出越长，越需要明确任务边界、停止条件与结果验证，而不是只相信整体文风。</p><h3 id="_3-3-生成长度不是思考深度" tabindex="-1">3.3 生成长度不是思考深度 <a class="header-anchor" href="#_3-3-生成长度不是思考深度" aria-label="Permalink to &quot;3.3 生成长度不是思考深度&quot;">​</a></h3><p>更多 Token 给模型更多中间表达空间，有时能改善复杂任务；但冗长内容也可能重复、偏题或扩大错误。应用应根据任务质量指标决定是否需要中间过程、简短答案或结构化字段，不能把输出长度直接当成推理质量。</p><h2 id="_4-参数化知识" tabindex="-1">4. 参数化知识 <a class="header-anchor" href="#_4-参数化知识" aria-label="Permalink to &quot;4. 参数化知识&quot;">​</a></h2><h3 id="_4-1-参数存储的是分布式模式" tabindex="-1">4.1 参数存储的是分布式模式 <a class="header-anchor" href="#_4-1-参数存储的是分布式模式" aria-label="Permalink to &quot;4.1 参数存储的是分布式模式&quot;">​</a></h3><p>训练会把有助于降低损失的模式编码到大量参数中。一条事实通常不是保存在某个可定位单元里，而是以分布式方式影响许多计算。模型可以组合模式回答训练中未原样出现的问题，但也难以像数据库那样精确列出来源、更新时间和置信记录。</p><h3 id="_4-2-参数知识与上下文信息不同" tabindex="-1">4.2 参数知识与上下文信息不同 <a class="header-anchor" href="#_4-2-参数知识与上下文信息不同" aria-label="Permalink to &quot;4.2 参数知识与上下文信息不同&quot;">​</a></h3><table tabindex="0"><thead><tr><th>信息来源</th><th>进入模型的时间</th><th>主要特点</th></tr></thead><tbody><tr><td>参数</td><td>训练阶段</td><td>覆盖广，更新成本高，来源难逐条追踪</td></tr><tr><td>当前上下文</td><td>请求阶段</td><td>临时、可控，受上下文窗口限制</td></tr><tr><td>外部工具结果</td><td>应用运行阶段</td><td>可获取最新或私有数据，需要应用集成和校验</td></tr></tbody></table><p>提示不会直接修改模型参数。把一份文档放入上下文，是让模型在本次请求中参考它，不是完成训练或永久记忆。</p><h3 id="_4-3-模型不是查询引擎" tabindex="-1">4.3 模型不是查询引擎 <a class="header-anchor" href="#_4-3-模型不是查询引擎" aria-label="Permalink to &quot;4.3 模型不是查询引擎&quot;">​</a></h3><p>数据库查询依据显式记录和查询语义返回结果；语言模型依据参数和上下文形成概率分布。即使答案与数据库记录相同，两者的正确性保证也不同。需要最新价格、账户余额、法规原文或精确出处时，应查询权威数据源，再让模型执行解释或转换。</p><h2 id="_5-确定性计算与随机选择" tabindex="-1">5. 确定性计算与随机选择 <a class="header-anchor" href="#_5-确定性计算与随机选择" aria-label="Permalink to &quot;5. 确定性计算与随机选择&quot;">​</a></h2><h3 id="_5-1-前向计算通常是数值函数" tabindex="-1">5.1 前向计算通常是数值函数 <a class="header-anchor" href="#_5-1-前向计算通常是数值函数" aria-label="Permalink to &quot;5.1 前向计算通常是数值函数&quot;">​</a></h3><p>固定模型参数和完全相同的输入时，一次理想化前向计算会得到确定的分数。随机性通常发生在解码策略从分布选择 Token 的阶段，而不是模型“随意改变知识”。</p><p>实际服务还可能因并行计算、数值精度、模型版本、路由或后端更新产生细微差异。因此“关闭采样”通常能提高重复性，但不能把跨时间、跨服务的逐字一致视为绝对保证。</p><h3 id="_5-2-最高概率与按概率采样" tabindex="-1">5.2 最高概率与按概率采样 <a class="header-anchor" href="#_5-2-最高概率与按概率采样" aria-label="Permalink to &quot;5.2 最高概率与按概率采样&quot;">​</a></h3><ul><li>贪心选择每次取概率最高的 Token，结果较稳定，但可能陷入重复或局部最优表达。</li><li>随机采样按处理后的概率分布选择，能增加多样性，也增加结果差异。</li><li>temperature、top-p 等参数改变选择分布，不会给模型补充缺失事实。</li></ul><p>具体解码机制在“推理与采样”中展开。这里需要先分清：模型给出分布，解码器从分布中决定实际输出。</p><h2 id="_6-从概率目标推导应用边界" tabindex="-1">6. 从概率目标推导应用边界 <a class="header-anchor" href="#_6-从概率目标推导应用边界" aria-label="Permalink to &quot;6. 从概率目标推导应用边界&quot;">​</a></h2><h3 id="_6-1-流畅是训练目标的直接结果" tabindex="-1">6.1 流畅是训练目标的直接结果 <a class="header-anchor" href="#_6-1-流畅是训练目标的直接结果" aria-label="Permalink to &quot;6.1 流畅是训练目标的直接结果&quot;">​</a></h3><p>预测下一个 Token 的训练会强烈奖励符合语言规律的续写，所以模型擅长产生连贯文本。事实核验、权限检查和业务约束并不是这个目标自动提供的保证。</p><h3 id="_6-2-提示改变条件-不改变保证" tabindex="-1">6.2 提示改变条件，不改变保证 <a class="header-anchor" href="#_6-2-提示改变条件-不改变保证" aria-label="Permalink to &quot;6.2 提示改变条件，不改变保证&quot;">​</a></h3><p>更清楚的提示可以收窄条件分布，让期望答案更可能出现；它不能把概率模型变成形式验证器。对金额、权限、医疗建议或可执行操作，应用仍需结构校验、业务校验和外部授权。</p><h3 id="_6-3-输出概率不等于事实置信度" tabindex="-1">6.3 输出概率不等于事实置信度 <a class="header-anchor" href="#_6-3-输出概率不等于事实置信度" aria-label="Permalink to &quot;6.3 输出概率不等于事实置信度&quot;">​</a></h3><p>某个 Token 的高概率表示它在当前模型和上下文下是强候选，不表示对应陈述在现实世界中有同样高的正确概率。语言模型可能非常确定地延续一个错误前提。</p><h2 id="_7-常见误解" tabindex="-1">7. 常见误解 <a class="header-anchor" href="#_7-常见误解" aria-label="Permalink to &quot;7. 常见误解&quot;">​</a></h2><h3 id="_7-1-模型在训练数据里搜索答案" tabindex="-1">7.1 “模型在训练数据里搜索答案” <a class="header-anchor" href="#_7-1-模型在训练数据里搜索答案" aria-label="Permalink to &quot;7.1 “模型在训练数据里搜索答案”&quot;">​</a></h3><p>普通生成不是逐条检索训练语料。模型用训练得到的参数进行计算。某些模型应用会额外接入搜索或检索，但那是外部系统能力。</p><h3 id="_7-2-相同提示必然得到相同答案" tabindex="-1">7.2 “相同提示必然得到相同答案” <a class="header-anchor" href="#_7-2-相同提示必然得到相同答案" aria-label="Permalink to &quot;7.2 “相同提示必然得到相同答案”&quot;">​</a></h3><p>采样、服务配置和模型版本都可能改变结果。需要可重复测试时，应固定可控配置、记录模型标识，并对语义或结构断言，而不是默认逐字相等。</p><h3 id="_7-3-概率最高的答案就是真实答案" tabindex="-1">7.3 “概率最高的答案就是真实答案” <a class="header-anchor" href="#_7-3-概率最高的答案就是真实答案" aria-label="Permalink to &quot;7.3 “概率最高的答案就是真实答案”&quot;">​</a></h3><p>最高概率只相对于模型学到的分布。事实正确性必须与权威数据、规则或可执行验证结合。</p><h2 id="_8-自测" tabindex="-1">8. 自测 <a class="header-anchor" href="#_8-自测" aria-label="Permalink to &quot;8. 自测&quot;">​</a></h2><ol><li>为什么一整段文本的概率可以拆成一系列下一个 Token 的条件概率？</li><li>自回归生成中，早期输出为什么会影响后续内容？</li><li>参数化知识与数据库记录在可更新性和可追溯性上有什么差异？</li><li>模型前向计算与解码选择分别负责什么？</li><li>为什么 Token 的高概率不能直接解释为事实的高置信度？</li></ol><p>能够把一次生成解释为“上下文决定分布，解码器选择 Token，选择结果进入下一轮”，就建立了理解后续 Token、Transformer 和采样机制的起点。</p>`,62)])])}const u=e(i,[["render",l]]);export{b as __pageData,u as default};
